package com.cheatprogram.gui;
import com.cheatprogram.core.*;import com.cheatprogram.render.*;import com.cheatprogram.util.WearModelStore;import net.minecraft.client.gui.GuiGraphicsExtractor;import net.minecraft.client.gui.screens.Screen;import org.lwjgl.glfw.GLFW;
/** One explicit code location per feature. Large asset codes are pasted/copied without rendering megabytes. */
public final class ScopedShareScreen extends GuiBase {
 private final Screen parent;private final ScopedPresetCodec.Scope scope;private final TextField input=new TextField(8192);private String code="",status="ui.scopedShare.hint";private boolean busy,closed;private long generation;
 public ScopedShareScreen(Screen parent,ScopedPresetCodec.Scope scope){super(Lang.t("ui.scopedShare.title"));this.parent=parent;this.scope=scope;input.onChange=s->{code="";status="ui.scopedShare.hint";};input.onEnter=()->read(false);}
 @Override protected void init(){closed=false;}
 @Override public void render(GuiGraphicsExtractor g,int mx,int my,float partial){beginFrame();if(!preparePanelBackground(g,partial)){endFrame();return;}R2D.begin(g);try{float h=layoutPanel(800,440);drawPanelSurface(g,800,h,22);c.textC(BOLD,Lang.t("ui.scopedShare.title")+" · "+Lang.t("module."+scope.module),24,31,15,Theme.TEXT);iconButton("scoped.close",Icon.CLOSE,772,30,14,Theme.TEXT_2,this::onClose);
  float y=65;for(String line:c.wrap(REG,Lang.t("ui.scopedShare.scopeHint"),10,748)){c.textC(REG,line,26,y+8,10,Theme.TEXT_2);y+=16;}y+=14;textField(input,"CPS1.…",Icon.LINK,24,y,752,34);y+=48;
  String length=code.isBlank()?"":Lang.t("ui.scopedShare.loaded",code.length());c.textC(REG,length,26,y,9,Theme.TEXT_3);y+=20;
  button("scoped.export",Lang.t("ui.scopedShare.export"),Icon.LINK,24,y,178,31,false,this::export);button("scoped.paste",Lang.t("ui.scopedShare.paste"),Icon.DOWNLOAD,214,y,178,31,false,this::paste);button("scoped.check",Lang.t("ui.scopedShare.validate"),Icon.CHECK,404,y,178,31,false,()->read(false));button("scoped.apply",Lang.t("ui.scopedShare.import"),Icon.DOWNLOAD,594,y,182,31,true,()->read(true));y+=53;
  String hint=scope==ScopedPresetCodec.Scope.PARTICLES?"ui.scopedShare.particlesHint":scope==ScopedPresetCodec.Scope.BUILDING?"ui.scopedShare.buildingHint":scope==ScopedPresetCodec.Scope.MODEL?"ui.scopedShare.modelHint":"ui.scopedShare.weaponHint";for(String line:c.wrap(REG,Lang.t(hint),9,748)){c.textC(REG,line,26,y+8,9,Theme.TEXT_3);y+=15;}y+=15;
  for(String line:c.wrap(REG,Lang.t(status),10,748)){c.textC(REG,line,26,y+8,10,Theme.TEXT_2);y+=16;}button("scoped.back",Lang.t("ui.back"),Icon.BACK,24,h-43,100,28,false,this::onClose);
 }finally{R2D.end();endFrame();}}
 private void paste(){if(busy)return;String clipboard=mc.keyboardHandler.getClipboard();if(clipboard.length()>ScopedPresetCodec.MAX_CODE){status="ui.scopedShare.tooLarge";return;}code=clipboard.strip();input.setText("");status="ui.scopedShare.hint";focused=null;}
 private void export(){if(busy)return;try{FeaturePresets.Snapshot snapshot=FeaturePresets.capture(scope);busy=true;status="ui.scopedShare.working";long token=++generation;WearModelStore.IO.execute(()->{String result="",error="";try{result=FeaturePresets.encode(snapshot);}catch(Exception failure){error=key(failure);}String value=result,message=error;mc.execute(()->{if(closed||generation!=token)return;busy=false;if(value.isBlank())status=message;else{code=value;input.setText("");mc.keyboardHandler.setClipboard(code);status="ui.scopedShare.copied";}});});}catch(Exception failure){status=key(failure);}}
 private void read(boolean apply){if(busy)return;String source=code.isBlank()?input.text:code;if(source.isBlank())return;busy=true;status="ui.scopedShare.working";long token=++generation;WearModelStore.IO.execute(()->{FeaturePresets.Prepared prepared=null;String installed="",error="";try{prepared=FeaturePresets.validate(ScopedPresetCodec.decode(scope,source));if(apply)installed=FeaturePresets.install(prepared);}catch(Exception failure){error=key(failure);}FeaturePresets.Prepared result=prepared;String asset=installed,message=error;mc.execute(()->{if(closed||generation!=token)return;busy=false;if(!message.isBlank()){status=message;return;}if(!apply){status="ui.scopedShare.valid";return;}try{FeaturePresets.apply(result,asset);status="ui.scopedShare.imported";}catch(Exception failure){status=key(failure);}});});}
 private static String key(Exception failure){String key=failure.getMessage();return key!=null&&(key.startsWith("ui.scopedShare.")||key.startsWith("ui.modelWear."))?key:"ui.scopedShare.invalid";}
 @Override public boolean mouseClicked(double x,double y,int b){if(!dispatchClick(x,y,b))focused=null;return true;}@Override public boolean mouseScrolled(double x,double y,double h,double v){return dispatchScroll(x,y,v);}@Override public boolean keyPressed(int k,int scan,int mods){if(k==GLFW.GLFW_KEY_ESCAPE){onClose();return true;}if((mods&GLFW.GLFW_MOD_CONTROL)!=0&&k==GLFW.GLFW_KEY_V){paste();return true;}return focused!=null&&focused.keyPressed(k,mods);}@Override public boolean charTyped(char c,int mods){return focused!=null&&focused.charTyped(c);}@Override public void onClose(){mc.setScreen(parent);}@Override public void removed(){closed=true;generation++;super.removed();}
}
